"""The free compliance checker's API: the public check gives away three compliances and no more, bad input is
refused, and a saved check belongs to one account only: it can be marked as filed, re-dated, re-answered and
removed by its owner and by nobody else. Runs against a running app."""
import sys, os, json
src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'flows_core.py')).read().split("section('Clients')")[0]
exec(src)

class Anon(Sess):
    def __init__(s): s.cookie = ''; s.op = urllib.request.build_opener()
anon = Anon()
SEL = {'country': 'CA', 'state': 'ON', 'entity': 'corporation', 'depts': ['income', 'sales', 'payroll', 'registry']}
ANS = {'ca_ccpc': 'yes', 'ca_sbd': 'yes', 'ca_federal': 'no', 'ca_pe': ['none'], 'ca_foreign_prop': 'no', 'ca_foreign_aff': 'no', 'ca_nr_related': 'no', 'ca_nrtrust_c': 'no', 'ca_nrtrust_d': 'no',
       'ca_corp_instal': 'no', 'ca_gst_reg': 'yes', 'ca_gst_freq': 'q', 'ca_sell_prov': ['none'], 'ca_employees': 'yes', 'ca_remit': 'r', 'ca_payroll_size': 'p1', 'ca_closing': 'no',
       'ca_contractors': 'no', 'ca_construction': 'no', 'ca_dividends': 'no', 'ca_pay_nr': 'no', 'fye': '12-31', 'ca_inc_date': '2020-03-15', 'ca_x_private': 'yes', 'ca_x_trademark': 'no'}

section('Public: no account needed')
st, j = anon.call('GET', '/api/public/compliance')
codes = [c['code'] for c in (j.get('countries') or [])] if st == 200 else []
step('the country list is public and has the four countries', st == 200 and set(['CA', 'US', 'IN', 'AE']) <= set(codes), (st, codes))
st, j = anon.call('GET', '/api/public/compliance?country=CA')
pack = j.get('pack') or {}
step('a country gives its provinces, entity types, departments and questions', st == 200 and len(pack.get('states', [])) == 13 and len(pack.get('questions', [])) >= 40, (st, list(pack.keys())))
step('but not the rules themselves (they stay on the server)', not pack.get('compliances') and not pack.get('sources'), (len(pack.get('compliances', [])), len(pack.get('sources', []))))
st, j = anon.call('GET', '/api/public/compliance?country=ZZ'); step('an unknown country is refused', st in (400, 404), st)

section('Public guide pages (for visitors and search engines)')
st, h = anon.call('GET', '/compliance'); step('the guide index opens without an account and lists the four countries', st == 200 and all(n in h for n in ['Canada', 'United States', 'India', 'United Arab Emirates']) and '<h1' in h, st)
st, h = anon.call('GET', '/compliance/canada'); step('a country page lists its kinds of person and business and its areas', st == 200 and 'href="/compliance/canada/corporation"' in h and 'By area' in h, st)
st, h = anon.call('GET', '/compliance/canada/corporation')
step('an entity page shows the main filings in full, each with its government source and the date it was checked', st == 200 and h.count('data-guide-item=') == 6 and 'Corporation income tax return' in h and 'Official government source:' in h and 'Last checked:' in h and 'canada.ca' in h, (st, h.count('data-guide-item=')))
step('and only counts the rest (the full personal list stays with the check)', 'T4 slips and summary' not in h and 'data-area=' in h, '')
step('it has its own title, description, canonical address and structured data', '<title>Compliance checklist for a corporation in Canada' in h and 'rel="canonical" href="https://www.abidebylaw.com/compliance/canada/corporation"' in h and 'application/ld+json' in h and 'BreadcrumbList' in h, h[:200])
st, h = anon.call('GET', '/compliance/canada/no-such'); step('an unknown page is a 404', st == 404, st)
st, h = anon.call('GET', '/sitemap.xml'); step('the sitemap lists the homepage and every guide page', st == 200 and h.count('<url>') >= 40 and 'https://www.abidebylaw.com/compliance/india/pvt' in h, (st, h.count('<url>')))
st, h = anon.call('GET', '/robots.txt'); step('robots.txt opens the site, keeps accounts and the API out, and names the sitemap', st == 200 and 'Disallow: /api/' in h and 'Disallow: /portal' in h and 'Sitemap: https://www.abidebylaw.com/sitemap.xml' in h, st)

section('Public: the check')
st, j = anon.call('POST', '/api/public/compliance', {'sel': SEL, 'answers': {}})
step('a check with unanswered questions is refused, saying which', st == 422 and len(j.get('missing', j.get('unanswered', []))) > 5, (st, str(j)[:160]))
st, j = anon.call('POST', '/api/public/compliance', {'sel': {**SEL, 'entity': 'adgm'}, 'answers': ANS}); step('an entity type that does not exist in that province is refused', st == 400, st)
st, j = anon.call('POST', '/api/public/compliance', {'sel': {**SEL, 'depts': ['bogus']}, 'answers': ANS}); step('an unknown department is refused', st == 400, st)
st, j = anon.call('POST', '/api/public/compliance', {'sel': SEL, 'answers': {**ANS, 'ca_ccpc': 'maybe'}}); step('an answer that is not one of the choices is refused', st in (400, 422), (st, str(j)[:120]))
st, R = anon.call('POST', '/api/public/compliance', {'sel': SEL, 'answers': ANS})
step('a complete check answers', st == 200 and R.get('total', 0) >= 7, (st, str(R)[:200]))
shown = R.get('shown', []); locked = R.get('locked', [])
step('exactly three compliances come back in full', len(shown) == 3 and all(x.get('name') and x.get('dueText') and x.get('sourceUrl', '').startswith('https://') for x in shown), [x.get('id') for x in shown])
import re
step('each names its government source and the date that page was last read', all(x.get('sourcePublisher') and re.match(r'^\d{4}-\d{2}-\d{2}$', x.get('sourceChecked') or '') for x in shown), [(x.get('sourcePublisher'), x.get('sourceChecked')) for x in shown])
step('the most important one first: the T2 return, due 30 June 2027', shown and shown[0]['id'] == 'ca_t2' and shown[0]['next'][0]['date'] == '2027-06-30', shown[0] if shown else '')
step('the others are only counted', len(locked) == R['total'] - 3 and all(set(l.keys()) <= {'head', 'frequency', 'certainty', 'due'} for l in locked), locked[:2])
blob = json.dumps(R)
step('no name, form or exact date of a locked compliance leaves the server', 'T4 slips' not in blob and 'ca_t4' not in blob and 'Payroll deductions remittance' not in blob, '')
ticket = R.get('ticket')
st, j = anon.call('POST', '/api/public/compliance', {'sel': SEL, 'answers': {**ANS, 'ca_employees': 'unsure'}})
step('"not sure" keeps the filing and marks it to be checked', st == 200 and j['total'] >= R['total'], (st, j.get('total')))

section('Saving needs an account')
st, j = anon.call('GET', '/api/compliance-tracker'); step('a visitor cannot read saved checks', st == 401, st)
st, j = anon.call('POST', '/api/compliance-tracker', {'ticket': ticket}); step('a visitor cannot save one', st == 401, st)
st, j = cli.call('POST', '/api/compliance-tracker', {'ticket': ticket + 'x'}); step('a tampered ticket is refused', st == 400, (st, j))
st, j = cli.call('POST', '/api/compliance-tracker', {'ticket': ticket, 'label': 'James Holdings Inc.'})
PID = j.get('id'); step('a signed-in person saves the check with its ticket', st == 200 and PID and j.get('created') == R['total'], (st, j))
st, j = cli.call('POST', '/api/compliance-tracker', {'ticket': ticket, 'label': 'again'}); step('saving the same check again does not duplicate it', st == 200 and j.get('id') == PID and j.get('existing'), (st, j))
n = psql(f"select count(*) from personal_entity_compliance where tracker_profile_id='{PID}'")
step('every compliance is in the person\'s vault, tied to the business', int(n) == R['total'] and psql(f"select name from personal_entities where id=(select vault_entity_id from compliance_tracker_profiles where id='{PID}')") == 'James Holdings Inc.', n)
st, j = cli.call('GET', '/api/compliance-tracker'); prof = (j.get('profiles') or [{}])[0]; items = prof.get('items', [])
step('the account lists them all, readable, with dates', st == 200 and len(items) == R['total'] and any(str(i.get('title', '')).startswith('T4 slips and summary') for i in items), (st, len(items)))

section('Tracking')
t2 = next(i for i in items if i['complianceId'] == 'ca_t2'); t4 = next(i for i in items if i['complianceId'] == 'ca_t4')
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': t2['id'], 'action': 'done'})
step('marking the T2 as filed rolls it to 30 June 2028 and keeps a history line', st == 200 and psql(f"select substr(due_date,1,10) from personal_entity_compliance where id='{t2['id']}'") == '2028-06-30' and psql(f"select count(*) from compliance_tracker_history where profile_id='{PID}'") == '1', (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': t4['id'], 'action': 'set_date', 'date': '2027-02-20'})
step('the owner can set their own date', st == 200 and psql(f"select substr(due_date,1,10) from personal_entity_compliance where id='{t4['id']}'") == '2027-02-20', (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': t4['id'], 'action': 'set_date', 'date': 'next week'}); step('a date that is not a date is refused', st == 400, (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'answers': {**ANS, 'ca_employees': 'no', 'ca_remit': None, 'ca_payroll_size': None, 'ca_closing': None}})
gone = psql(f"select count(*) from personal_entity_compliance where tracker_profile_id='{PID}' and tracker_compliance_id='ca_remit_r' and status<>'completed'")
st2, j2 = cli.call('GET', '/api/compliance-tracker'); items2 = (j2.get('profiles') or [{}])[0].get('items', [])
step('changing an answer re-works the list (no employees: the payroll filings no longer apply)', st == 200 and not any(i['complianceId'] == 'ca_remit_r' and i.get('stillApplies', True) for i in items2), (st, gone, [i['complianceId'] for i in items2][:12]))
step('and the T2 they already marked as filed does not come back: it stays on 30 June 2028', psql(f"select substr(due_date,1,10) from personal_entity_compliance where id='{t2['id']}'") == '2028-06-30', psql(f"select substr(due_date,1,10) from personal_entity_compliance where id='{t2['id']}'"))

section('The person adds, changes and removes things themselves')
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'action': 'add_own', 'title': 'City business licence renewal', 'date': '2026-11-25', 'repeat': 'annual', 'note': 'Renew online'})
OWN = j.get('id'); step('add something of their own with a date that repeats', st == 200 and OWN, (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'action': 'add_own', 'title': ' ', 'date': '2026-11-25'}); step('it needs a name', st == 400, (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'action': 'add_own', 'title': 'x', 'repeat': 'annual'}); step('something that repeats needs its first date', st == 400, (st, j))
st, j = cli.call('GET', f'/api/compliance-tracker?options={PID}'); opts = j.get('options', [])
have = [i['complianceId'] for i in (cli.call('GET', '/api/compliance-tracker')[1]['profiles'][0]['items'])]
step('the list of what can be added leaves out what they already have', st == 200 and len(opts) > 50 and not any(o['id'] in have for o in opts) and any(o['id'] == 'ca_t1135' for o in opts), (st, len(opts)))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'action': 'add', 'complianceId': 'ca_t1135'}); step('add a compliance from the list that their answers did not lead to', st == 200, (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'action': 'add', 'complianceId': 'ca_t1135'}); step('the same one cannot be added twice', st == 400, (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'action': 'add', 'complianceId': 'no_such'}); step('nor one that does not exist', st == 400, (st, j))
st, j = cli.call('GET', '/api/compliance-tracker'); its = {i['complianceId']: i for i in j['profiles'][0]['items']}
own = next(i for i in j['profiles'][0]['items'] if i['id'] == OWN); t1135 = its.get('ca_t1135', {})
step('both show in the list: their own under "My own", the other with its rule, source and next date', own['head'] == 'My own' and own['own'] and own['dueDate'][:10] == '2026-11-25' and t1135.get('manual') and t1135.get('stillApplies') and t1135.get('sourceUrl', '').startswith('https://') and t1135.get('dueDate'), (own.get('head'), t1135.get('manual'), t1135.get('dueDate')))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'answers': {**ANS, 'ca_employees': 'no', 'ca_remit': None, 'ca_payroll_size': None, 'ca_closing': None, 'ca_dividends': 'yes'}})
st2, j2 = cli.call('GET', '/api/compliance-tracker'); ids = [i['complianceId'] for i in j2['profiles'][0]['items']]
step('changing an answer afterwards keeps both', st == 200 and 'ca_t1135' in ids and own['complianceId'] in ids, (st, ids))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': OWN, 'action': 'done'})
step('marking their own yearly item as done moves it a year on', st == 200 and j.get('next') == '2027-11-25', (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': OWN, 'action': 'edit', 'title': 'City licence', 'note': 'Paid by card'})
step('their own item can be renamed and given a note', st == 200 and psql(f"select title || '|' || notes from personal_entity_compliance where id='{OWN}'") == 'City licence|Paid by card', (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': t2['id'], 'action': 'edit', 'title': 'Renamed'}); step('a compliance from the rules cannot be renamed', st == 400, (st, j))
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': t2['id'], 'action': 'edit', 'note': 'With the accountant'}); step('but it can carry the person\'s note', st == 200 and psql(f"select notes from personal_entity_compliance where id='{t2['id']}'") == 'With the accountant', (st, j))

section('A calendar file of the due dates')
r = urllib.request.Request(B + '/api/compliance-tracker/calendar', headers={'Cookie': cli.cookie})
with cli.op.open(r) as resp: ics = resp.read().decode(); ctype = resp.headers.get('Content-Type', '')
step('the owner downloads every open due date as a calendar file with reminders', ctype.startswith('text/calendar') and ics.count('BEGIN:VEVENT') >= 6 and 'TRIGGER:-P7D' in ics and 'T2' in ics.replace('\r\n ', '') and 'Official source: https://' in ics.replace('\r\n ', ''), (ctype, ics.count('BEGIN:VEVENT')))
st, j = anon.call('GET', '/api/compliance-tracker/calendar'); step('a visitor gets nothing', st == 401, st)
r = urllib.request.Request(B + '/api/compliance-tracker/calendar', headers={'Cookie': adm.cookie})
with adm.op.open(r) as resp: other = resp.read().decode()
step('another account\'s file has none of it', 'Maple' not in other and 'James Holdings' not in other and other.count('BEGIN:VEVENT') == 0, other.count('BEGIN:VEVENT'))

section('Papers kept with a compliance')
def upload(sess, profile, cid, name, data):
    bnd = 'x' + uid() + uid()
    body = b''.join([f'--{bnd}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode() for k, v in (('profileId', profile), ('complianceId', cid))])
    body += f'--{bnd}\r\nContent-Disposition: form-data; name="file"; filename="{name}"\r\nContent-Type: application/octet-stream\r\n\r\n'.encode() + data + f'\r\n--{bnd}--\r\n'.encode()
    return sess.call('POST', '/api/compliance-tracker/documents', raw=body, headers={'Content-Type': f'multipart/form-data; boundary={bnd}'})
PDF = b'%PDF-1.4 test file for the T2 ' + bytes(range(256))
st, j = upload(cli, PID, 'ca_t2', 'T2 filed 2026.pdf', PDF); DOC = j.get('id'); step('the owner adds a file to a compliance', st == 200 and DOC, (st, j))
st, j = cli.call('GET', '/api/compliance-tracker'); d = next(i for i in j['profiles'][0]['items'] if i['complianceId'] == 'ca_t2')['docs']
step('it is listed with that compliance', len(d) == 1 and d[0]['name'] == 'T2 filed 2026.pdf' and d[0]['size'] == len(PDF), d)
r = urllib.request.Request(B + f'/api/compliance-tracker/documents?id={DOC}', headers={'Cookie': cli.cookie})
with cli.op.open(r) as resp: got = resp.read(); disp = resp.headers.get('Content-Disposition', '')
step('and comes back byte for byte', got == PDF and 'attachment' in disp, (len(got), disp))
st, j = upload(cli, PID, 'ca_t2', 'virus.exe', b'MZ'); step('a file type that is not a document is refused', st == 400, (st, j))
st, j = upload(cli, PID, 'ca_t2', 'big.pdf', b'0' * (4 * 1024 * 1024 + 10)); step('a file over 4 MB is refused', st in (400, 413), st)
st, j = upload(cli, PID, 'no_such', 'a.pdf', PDF); step('a file for a compliance not in the list is refused', st == 404, (st, j))
st, j = upload(adm, PID, 'ca_t2', 'a.pdf', PDF); step('another user cannot add a file to it', st == 404, (st, j))
st, j = adm.call('GET', f'/api/compliance-tracker/documents?id={DOC}'); step('cannot download it', st == 404, st)
st, j = adm.call('DELETE', f'/api/compliance-tracker/documents?id={DOC}'); step('cannot delete it', st == 404 and psql(f"select count(*) from compliance_tracker_documents where id='{DOC}'") == '1', st)
st, j = anon.call('GET', f'/api/compliance-tracker/documents?id={DOC}'); step('a visitor cannot download it', st == 401, st)
st, j = upload(cli, PID, own['complianceId'], 'licence.png', b'\x89PNG test'); D2 = j.get('id')
st, j = cli.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': OWN, 'action': 'remove'})
step('removing an item removes its papers with it', st == 200 and psql(f"select count(*) from compliance_tracker_documents where id='{D2}'") == '0' and psql(f"select count(*) from compliance_tracker_documents where id='{DOC}'") == '1', (st, j))
st, j = cli.call('DELETE', f'/api/compliance-tracker/documents?id={DOC}'); step('the owner deletes a file', st == 200 and psql(f"select count(*) from compliance_tracker_documents where id='{DOC}'") == '0', (st, j))
st, j = upload(cli, PID, 'ca_t2', 'kept.pdf', PDF); D3 = j.get('id')

section('One account cannot touch another\'s')
st, j = adm.call('GET', '/api/compliance-tracker'); step('another user sees nothing of it', st == 200 and not any(p.get('id') == PID for p in j.get('profiles', [])), (st, str(j)[:120]))
st, j = adm.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'itemId': t2['id'], 'action': 'done'}); step('cannot mark its filings', st == 404, st)
st, j = adm.call('PATCH', '/api/compliance-tracker', {'profileId': PID, 'answers': ANS}); step('cannot change its answers', st == 404, st)
st, j = adm.call('DELETE', f'/api/compliance-tracker?profileId={PID}'); step('cannot remove it', st == 404 and psql(f"select count(*) from compliance_tracker_profiles where id='{PID}' and status='active'") == '1', st)
st, j = plat.call('GET', '/api/compliance-tracker'); step('the platform administrator does not see a person\'s saved checks here either', st == 200 and not any(p.get('id') == PID for p in j.get('profiles', [])), st)
st, j = cli.call('DELETE', f'/api/compliance-tracker?profileId={PID}')
left = psql(f"select count(*) from personal_entity_compliance where tracker_profile_id='{PID}' and status<>'completed'")
step('the owner can remove the check; its open filings go with it', st == 200 and left == '0', (st, left))
step('and so do its papers', psql(f"select count(*) from compliance_tracker_documents where id='{D3}'") == '0', '')

print(f'\ncompliance_api: {P} passed, {F} failed'); sys.exit(1 if F else 0)
